# Blok http — definisikan zona sekali, pakai di banyak location
http {
    # 10 request/detik per IP; zona 10m ~ 160 ribu IP
    limit_req_zone $binary_remote_addr zone=api:10m rate=10r/s;
    limit_req_zone $binary_remote_addr zone=login:10m rate=1r/s;

    server {
        listen 80;
        server_name api.example.id;

        location /api/ {
            # burst 20: 20 request berlebih diantrekan, diproses tanpa delay
            limit_req zone=api burst=20 nodelay;
            # Status saat limit tercapai: 429 (default 503)
            limit_req_status 429;
            proxy_pass http://app_backend;
        }

        location /login {
            # Login jauh lebih ketat: 1 request/detik, burst 5
            limit_req zone=login burst=5 nodelay;
            limit_req_status 429;
            proxy_pass http://app_backend;
        }
    }
}

http {
    # Hitung koneksi bersamaan per IP
    limit_conn_zone $binary_remote_addr zone=conn_per_ip:10m;

    server {
        listen 80;
        server_name files.example.id;

        location /download/ {
            # Maks 10 koneksi bersamaan per IP
            limit_conn conn_per_ip 10;
            # Status saat batas tercapai (default 503)
            limit_conn_status 429;
            proxy_pass http://app_backend;
        }
    }
}

# Blokir IP / subnet tertentu (letakkan di server atau location)
location /admin/ {
    allow 192.168.1.0/24;   # hanya jaringan kantor
    allow 10.0.0.5;         # IP admin
    deny all;               # sisanya ditolak (403)
    proxy_pass http://app_backend;
}

# Geo blocking berdasarkan negara (butuh database GeoIP)
http {
    geo $blocked_country {
        default 0;
        # Contoh: tolak negara yang tidak pernah jadi target layananmu
        XX 1;
    }

    server {
        location / {
            if ($blocked_country) {
                return 403;
            }
            proxy_pass http://app_backend;
        }
    }
}

http {
    # Tandai user-agent yang dikenal sebagai bot/scraper
    map $http_user_agent $bad_bot {
        default 0;
        # Cocokkan sebagian string (case-insensitive)
        ~* (scrapy|httrack|sqlmap|nikto|nmap) 1;
        # User-Agent kosong juga mencurigakan
        "" 1;
    }

    server {
        location / {
            if ($bad_bot) {
                return 403;
            }
            proxy_pass http://app_backend;
        }
    }
}

server {
    listen 443 ssl http2;
    server_name app.example.id;

    # Mencegah clickjacking (jangan di-embed iframe situs lain)
    add_header X-Frame-Options "SAMEORIGIN" always;
    # Mencegah browser menebak tipe konten (MIME sniffing)
    add_header X-Content-Type-Options "nosniff" always;
    # Referer hanya dikirim ke origin yang sama
    add_header Referrer-Policy "same-origin" always;
    # Hanya izinkan resource dari origin sendiri (+ CDN yang kamu percaya)
    add_header Content-Security-Policy "default-src 'self'; img-src 'self' data:; script-src 'self'" always;
    # Paksa HTTPS selama 1 tahun (hanya kalau situs sudah full HTTPS)
    add_header Strict-Transport-Security "max-age=31536000; includeSubDomains" always;

    location / {
        proxy_pass http://app_backend;
    }
}
